INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(88427, 'ruRU', 'Я готов спуститься к Башне Эйгвин.', '', 24330),
(88528, 'ruRU', 'Нужно снова зажечь обереги. Иначе, я гарантирую, Легион прорвёт нашу оборону и хлынет в Азсуну.', '', 24330),
(88529, 'ruRU', 'Твой орден рассыпается. Преданный изнутри... проклятие, которое ты будешь нести целую вечность.', '', 24330),
(88611, 'ruRU', 'ДОЛЖЕН быть способ пройти мимо этих статуй.$b$bЯ хочу удалиться в свои покои, но совы прогоняют меня каждый раз, когда я подхожу к ним. А я так устал...', '', 24330),
(88612, 'ruRU', 'Что ж, полагаю, ты мог бы пройти мимо них, если бы стал |cFF0000FF[Невидимым]|r...', '', 24330),
(88613, 'ruRU', 'Я найду способ пройти мимо сов.', '', 24330),
(88614, 'ruRU', 'Мне нужна помощь! Как пройти мимо сов?', '', 24330),
(88619, 'ruRU', 'Мой желудок урчит всё громче с каждым годом. Мне бы не помешало перекусить.$b$bЯ, пожалуй, мог бы даже отдать тебе свой свиток, если ты поможешь утолить этот голод.', '', 24330),
(88620, 'ruRU', 'Хм... ты, похоже, что-то вроде заклинателя. У тебя наверняка есть способ |cFF0000FF[Сотворить угощение]|r для меня...', '', 24330),
(88621, 'ruRU', 'Я раздобуду тебе еды.', '', 24330),
(88622, 'ruRU', 'Мне нужна помощь! Что мне сделать, чтобы накормить голодного спутника?', '', 24330),
(88623, 'ruRU', 'Мне и правда пора уложить дочь спать. Уже на века позже её отбоя.$b$bНо я никак не могу пройти сквозь эти стены. Что остаётся родителю?', '', 24330),
(88624, 'ruRU', 'Дети растут так быстро. |cFF0000FF[Мигание]|r дважды — и они уже взрослые...', '', 24330),
(88625, 'ruRU', 'Я найду способ пройти сквозь стены.', '', 24330),
(88626, 'ruRU', 'Мне нужна помощь! Как пройти сквозь эти стены?', '', 24330),
(88627, 'ruRU', 'Хозяин попросил меня избавить лицей от грызунов. Но вот с одной крысой мне совсем не справиться.', '', 24330),
(88628, 'ruRU', 'На этой твари мощные чары. Конечно, могущественный маг мог бы как-нибудь |cFF0000FF[Похитить чары]|r, но я всего лишь парень с метлой...', '', 24330),
(88629, 'ruRU', 'Я одолею её для тебя.', '', 24330),
(88631, 'ruRU', 'Мне нужна помощь! Как одолеть это чудовище?', '', 24330),
(88634, 'ruRU', 'Вместе мы снова запечатаем Гробницу Саргераса и одолеем Пылающий Легион.', '', 24330),
(88635, 'ruRU', 'Я готов отправиться на поиски своего артефакта!', '', 24330),
(88644, 'ruRU', 'Еда! Прошу, забери мой свиток заклинания, он мне больше не нужен.', '', 24330),
(88745, 'ruRU', '<Книга полна заклинаний — некоторые странные, многие знакомые. Одно заклинание вызывает особый интерес.>', '', 24330),
(88746, 'ruRU', '<Произнесите заклинание, чтобы призвать Алунет.>', '', 24330),
(88752, 'ruRU', '"Великий посох Алунет обитает в плане, недостижимом для всех, кроме самых искусных чародеев. Верховный маг Рентаррик первым призвал его. Я была последней."$b$b- Магна Эйгвин', '', 24330),
(88753, 'ruRU', '"Алунет будет сопротивляться тем, кто попытается им овладеть. Своенравный дух великого посоха нужно сперва сломить."$b$b- Магна Эйгвин', '', 24330),
(88754, 'ruRU', '"Алунет капризен. Сущность нужно быстро связать с её призывателем, пока любопытство не увело её прочь."$b$b- Магна Эйгвин', '', 24330),
(88755, 'ruRU', '"Сила Алунета должна быть сразу очевидна тому, кто им владеет. Однако его тонкости станут яснее только со временем."$b$b- Магна Эйгвин', '', 24330),
(88756, 'ruRU', '"Когда Алунет не используется, ему нужно позволять возвращаться в свой план."$b$b- Магна Эйгвин', '', 24330),
(88768, 'ruRU', 'Аах... Алунет. Ты говоришь о великом посохе Магны.$b$bЯ с самого начала знала, что это не обычное оружие. Моя госпожа просто протягивала руку вверх и ХВАТАЛА посох прямо из воздуха, слегка им размахивала, а затем... просто КЛАЛА его обратно в тот же воздух, откуда он взялся.$b$bНикакого сокрытия или шарлатанской невидимости здесь не было. Этот посох явился из другого мира. И Магна знала, как дотянуться до того мира и выхватить его оттуда.', '', 24330),
(88769, 'ruRU', 'Я однажды видел это великое оружие в библиотеке госпожи — оно само двигалось среди полок!$b$bЯ сделал вид, что не заметил, но боюсь, оно заметило мой взгляд.', '', 24330),
(88770, 'ruRU', 'Ты про оружие Магны? Я могу рассказать, что знаю.$b$bОднажды, когда я был намного, намного младше, я потянулся, чтобы коснуться великого посоха — госпожа оставила его прислонённым к двери своих покоев. Посох отверг моё прикосновение болезненными щупальцами розовой и фиолетовой молнии.$b$bНи секунды не прошло, как появилась Магна и вырвала оружие у меня из рук.$b$bЕё с этим посохом связывали узы, которых мне никогда не понять до конца.', '', 24330),
(88771, 'ruRU', 'Это оружие... Я никогда не видел ничего подобного.$b$bМоя госпожа разговаривала с этой штукой, будто она живая. Говорила о заклинаниях, ритуалах, других тайнах чародейства... всё это было выше моего понимания.$b$bОна всегда была немного дикой, моя госпожа, но чокнутой мне не казалась никогда. Хотя странно всё же — разговаривать с посохом.', '', 24330),
(88772, 'ruRU', 'Что ты можешь рассказать мне об Алунете?', '', 24330),
(88933, 'ruRU', 'Бликети-сликети ук. Этот манк джикнул на мой дук. Рожа! А ну, давай сюда бойцовскую жрачку!', '', 24330),
(88936, 'ruRU', 'Если бы нам не нужна была поддержка этих великанов, я бы убил тебя на месте.', '', 24330),
(88937, 'ruRU', 'Еды тебе сегодня не будет, раб.', '', 24330),
(90212, 'ruRU', 'Я... не скажу... тебе!', '', 24330),
(90222, 'ruRU', 'Я сказал, когда я избил твоего брата до посинения, он обделался и убежал. А теперь дай мне жрачку!', '', 24330),
(90223, 'ruRU', 'Эй, Ука, у тебя укер наружу торчит. Это неаппетитно и совсем негигиенично.', '', 24330);
